INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvorfor betod alliancesystemet at en lokal konflikt hurtigt blev en verdenskrig?","options":["Fordi hvert land der gik i krig automatisk trak sine allierede med ind","Fordi alliancerne forbod lande at foere krig mod hinanden","Fordi alle lande i verden var med i den samme alliance","Fordi ingen lande ville hjaelpe hinanden og det skabte kaos"],"correct":"Fordi hvert land der gik i krig automatisk trak sine allierede med ind","accepted_answers":["Fordi hvert land der gik i krig automatisk trak sine allierede med ind"],"review_text":"Oestrig-Ungarn erklaerede krig mod Serbien. Rusland mobiliserede for at hjaelpe Serbien. Germany erklaerede krig mod Rusland. Frankrig og England kom ind. Paa faa uger var en lokal konflikt blevet en europaeisk krig."}'::jsonb,
  'mc','short','{"concepts":["alliancer","kaedereaktion","eskalering","verdenskrig"],"misconception_type":"causal_inversion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',2,'auto',true,'world_war_1',7,2
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var forholdet mellem mordet paa Franz Ferdinand og Forste Verdenskrigs udbrud?","options":["Mordet var den gnist der udloeste krigen men de egentlige aarsager var dybe spaendinger der havde bygget op i aartier","Mordet var den eneste og direkte aarsag til krigen","Mordet var uvaesentligt og krigen ville have brudt ud uanset hvad","Mordet foraarsakede kun en kortvarig konflikt mellem Oestrig og Serbien"],"correct":"Mordet var den gnist der udloeste krigen men de egentlige aarsager var dybe spaendinger der havde bygget op i aartier","accepted_answers":["Mordet var den gnist der udloeste krigen men de egentlige aarsager var dybe spaendinger der havde bygget op i aartier"],"review_text":"Franz Ferdinand var gnisten ikke aarsagen. Nationalisme, rustningskaapplobet, imperialisme og alliancesystemet havde bygget op i aaratier. Mordet var blot den begivenhed der satte det hele i gang."}'::jsonb,
  'mc','short','{"concepts":["Franz Ferdinand","gnist","strukturelle aarsager","MAIN","misconception-en-aarsag"],"misconception_type":"causal_inversion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',2,'auto',true,'world_war_1',7,2
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvorfor var skyttegravskrigen saa dodelig?","options":["Maskingevaerer dræbte alle der angreb over aabent terrae og skaabte en blodig doedvande","Soldaterne var traeante til at doe og betragtede det ikke som et problem","Skyttegravene var kun til pynt og kampen foregik egentlig andre steder","Teknologien var saa ny at soldaterne ikke vidste hvad de foretog sig"],"correct":"Maskingevaerer dræbte alle der angreb over aabent terrae og skaabte en blodig doedvande","accepted_answers":["Maskingevaerer dræbte alle der angreb over aabent terrae og skaabte en blodig doedvande"],"review_text":"Et enkelt maskingevaer kunne dræbe hundredvis af angribende soldater paa minutter. Forsvar var nu langt stærkere end angreb. Det betod at krigen gik i staa i aaarevis mens begge sider led enorme tab."}'::jsonb,
  'mc','short','{"concepts":["maskingevaer","defensiv teknologi","doedvande","tab","skyttegrave"],"misconception_type":"false_equivalence","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',2,'auto',true,'world_war_1',7,2
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var formaaalet med propaganda under Forste Verdenskrig?","options":["At holde befolkningens moral oppe, rekruttere soldater og fremstille fjenden som ond","At formidle objektiv information om krigens foerlob til borgerne","At koordinere militaere operationer mellem allierede","At kommunikere med soldaterne ved fronten"],"correct":"At holde befolkningens moral oppe, rekruttere soldater og fremstille fjenden som ond","accepted_answers":["At holde befolkningens moral oppe, rekruttere soldater og fremstille fjenden som ond"],"review_text":"Alle krigsfoerende lande brugte propaganda aktivt. Plakater og film fremstillede fjenden som barbarisk. Det var vigtigt for at faa maeand til at melde sig og faa befolkningen til at stoette krigen."}'::jsonb,
  'mc','short','{"concepts":["propaganda","moral","rekruttering","fjendebillede","manipulation"],"misconception_type":"scope_confusion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',2,'auto',true,'world_war_1',7,2
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvordan ramte Forste Verdenskrig civile bag fronten?","options":["Via rationering af mad, bomninger af byer og sorgen over at miste familiemedlemmer","Civile var fuldt beskyttede og maerkede naesten ikke krigen","Kun civile nær fronten maerkede krigen","Civile tjente penge fordi fabrikker arbejdede haardere"],"correct":"Via rationering af mad, bomninger af byer og sorgen over at miste familiemedlemmer","accepted_answers":["Via rationering af mad, bomninger af byer og sorgen over at miste familiemedlemmer"],"review_text":"Krigen var ikke kun for soldater. Civile maerkede den via madmangel, bombeangreb og den konstante frygt for at miste en far, bror eller son. For mange familier varede sorgen i aartier."}'::jsonb,
  'mc','short','{"concepts":["civile","hjemmefront","rationering","bomninger","misconception-kun-soldater"],"misconception_type":"scope_confusion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',2,'auto',true,'world_war_1',7,2
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvorfor fortsatte soldaterne med at kaempe i de frygtelige skyttegraver aar efter aar?","options":["Kombination af pligtsfolelse, kammeratskab, frygt for straf og propaganda om aere og heroisme","Fordi de syntes det var spaeaendende","Fordi de ikke vidste hvad der foregik","Fordi de alle troede krigen ville slutte inden for faa uger"],"correct":"Kombination af pligtsfolelse, kammeratskab, frygt for straf og propaganda om aere og heroisme","accepted_answers":["Kombination af pligtsfolelse, kammeratskab, frygt for straf og propaganda om aere og heroisme"],"review_text":"Soldaterne fortsatte ikke kun af mod. Kammeratskab, pligtsfolelse og frygt for militaer straf holdt dem i graevterne. Desertore risikerede doedsstraffen. Propaganda overbeviste mange om at de kaeempede for et hoejere formaal."}'::jsonb,
  'mc','short','{"concepts":["soldater","kammeratskab","pligtsfolelse","straf","propaganda"],"misconception_type":"false_equivalence","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"perspective_shift","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',2,'auto',true,'world_war_1',7,2
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var rustningskaapplobet foer Forste Verdenskrig?","options":["En konkurrence mellem de store magter om at opbygge storre og stærkere haer og flaader end sine rivaler","En konkurrence om at bygge de bedste jernbaner i Europa","En konkurrence om at erobre flest kolonier i Afrika","En aftale om at dele militaere teknologier med hinanden"],"correct":"En konkurrence mellem de store magter om at opbygge storre og stærkere haer og flaader end sine rivaler","accepted_answers":["En konkurrence mellem de store magter om at opbygge storre og stærkere haer og flaader end sine rivaler"],"review_text":"Isaer England og Germany havde et intenst kaapplob om floestyrke. Begge lande byggede krigssskibe i et rasende tempo. Det skabte frygt og mistillid og goerede krig mere sandsynlig."}'::jsonb,
  'mc','short','{"concepts":["rustningskaapplob","militarisme","flaaade","Germany","England","spaending"],"misconception_type":"false_equivalence","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',2,'auto',true,'world_war_1',7,2
);

