INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er forkert ved forestillingen om at nationalisme altid var positiv foer Forste Verdenskrig?","options":["Nationalisme skabte ogsaa had til andre folkegrupper og rivalisering der goerede krig mere sandsynlig","Forestillingen er korrekt nationalisme var altid en positiv kraft","Nationalisme forhindrede faktisk krig ved at gore hvert land selvtilstraekkeligt","Nationalisme eksisterede ikke foer Forste Verdenskrig"],"correct":"Nationalisme skabte ogsaa had til andre folkegrupper og rivalisering der goerede krig mere sandsynlig","accepted_answers":["Nationalisme skabte ogsaa had til andre folkegrupper og rivalisering der goerede krig mere sandsynlig"],"review_text":"Nationalisme kan vaere positiv som stolthed over sin kultur. Men den kan ogsaa vaere farlig naar den betyder at man ser andre nationer som fjender. I perioden foer 1914 skabte nationalisme rivalisering der bidrog til krigen."}'::jsonb,
  'mc','short','{"concepts":["nationalisme","had","rivalisering","misconception-nationalisme-positiv","dobbelttydig"],"misconception_type":"overgeneralization","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"world_war_1"}'::jsonb,
  'mc_single',3,'auto',true,'world_war_1',7,3
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er forkert ved forestillingen om at mordet paa Franz Ferdinand alene foraarsagede Forste Verdenskrig?","options":["Krigen havde fire dybe strukturelle aarsager bygget op i aartier: nationalisme, alliancer, imperialisme og militarisme","Forestillingen er korrekt mordet var den eneste reelle aarsag","Det er forkert fordi krigen ikke havde noget med mordet at goere","Det er forkert fordi det var Rusland der startede krigen"],"correct":"Krigen havde fire dybe strukturelle aarsager bygget op i aartier: nationalisme, alliancer, imperialisme og militarisme","accepted_answers":["Krigen havde fire dybe strukturelle aarsager bygget op i aartier: nationalisme, alliancer, imperialisme og militarisme"],"review_text":"Historikere bruger forkortelsen MAIN: Militarisme, Alliancer, Imperialisme, Nationalisme. Mordet var gnisten der taeaendte en situation der allerede var ekstremt spraeangfarlig. Fjern mordet og krigen ville sandsynligvis stadig have brudt ud."}'::jsonb,
  'mc','short','{"concepts":["MAIN","enkelt-aarsag","strukturelle aarsager","misconception-en-aarsag","Franz Ferdinand"],"misconception_type":"causal_inversion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"world_war_1"}'::jsonb,
  'mc_single',3,'auto',true,'world_war_1',7,3
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er forkert ved forestillingen om at ny teknologi goerede krigen lettere for soldaterne?","options":["Ny teknologi skaabte de vaerst taenkelige vilkaar og goerede krigen endnu mere dodelig og langvarig","Forestillingen er korrekt teknologien hjalp soldaterne med at vinde hurtigt","Teknologien aendrede intet i praksis","Teknologien skadede primaert civile ikke soldaterne"],"correct":"Ny teknologi skaabte de vaerst taenkelige vilkaar og goerede krigen endnu mere dodelig og langvarig","accepted_answers":["Ny teknologi skaabte de vaerst taenkelige vilkaar og goerede krigen endnu mere dodelig og langvarig"],"review_text":"Giftgas, maskingevaerer og artilleri skabte et af historiens blodigste slagmarker. Teknologien styrkede forsvaret men svaekkede angrebet. Det skaabte en doedvande der kostede millioner af liv og varede fire aar."}'::jsonb,
  'mc','short','{"concepts":["teknologi","doedvande","dodelig","misconception-teknologi-lettere","artilleri"],"misconception_type":"causal_inversion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"world_war_1"}'::jsonb,
  'mc_single',3,'auto',true,'world_war_1',7,3
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var den langsigtede konsekvens af kvinders indsats under Forste Verdenskrig?","options":["Det hjalp med at aendre synet paa kvinder som kompetente deltagere i samfundet og styrkede stemmeretsbevaeegelsen","Kvinder vendte straks tilbage til de gamle roller da krigen sluttede og intet aendrede sig","Krigen svaekkede kvinders position i samfundet","Kvindernes roller aendrede sig kun i England"],"correct":"Det hjalp med at aendre synet paa kvinder som kompetente deltagere i samfundet og styrkede stemmeretsbevaeegelsen","accepted_answers":["Det hjalp med at aendre synet paa kvinder som kompetente deltagere i samfundet og styrkede stemmeretsbevaeegelsen"],"review_text":"I mange lande fik kvinder stemmeret kort efter krigen: England i 1918, USA i 1920. Krigen havde bevist at kvinder var fuldt kompetente til at drive samfundet. Det var svaert at tage den erkendelse tilbage."}'::jsonb,
  'mc','short','{"concepts":["kvinder","stemmeret","kompetence","langsigtede konsekvenser","forandring"],"misconception_type":"temporal_confusion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"world_war_1"}'::jsonb,
  'mc_single',3,'auto',true,'world_war_1',7,3
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er forkert ved forestillingen om at Versailles-traktaten loeste Europas problemer?","options":["Traktaten ydmygede Germany saa haardt at den skabte de betingelser Hitler senere udnyttede","Forestillingen er korrekt traktaten skabte varig fred","Traktaten var for mild mod Germany og det var problemet","Traktaten loeste problemerne men kun til 1920"],"correct":"Traktaten ydmygede Germany saa haardt at den skabte de betingelser Hitler senere udnyttede","accepted_answers":["Traktaten ydmygede Germany saa haardt at den skabte de betingelser Hitler senere udnyttede"],"review_text":"Versailles paaloede Germany skylden for hele krigen og kraevede gigantiske erstatninger. Den tyske befolkning oplevede det som en dyb ydmygelse. Det skabte bitter vrede der gav Hitler og nationalsocialismen gunstige betingelser."}'::jsonb,
  'mc','short','{"concepts":["Versailles","ydmygelse","Hitler","konsekvenser","misconception-Versailles-loeste"],"misconception_type":"temporal_confusion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"world_war_1"}'::jsonb,
  'mc_single',3,'auto',true,'world_war_1',7,3
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er forbindelsen mellem Forste og Anden Verdenskrig?","options":["Versailles-traktatens haarde betingelser skabte okonomisk nod og national ydmygelse i Germany der banede vejen for Hitler","Der er ingen forbindels de to krige var fuldstaendig uafhaengige","Forbindelsen er at de samme lande kaeampede mod hinanden","Forbindelsen er kun geografisk begge fandt sted i Europa"],"correct":"Versailles-traktatens haarde betingelser skabte okonomisk nod og national ydmygelse i Germany der banede vejen for Hitler","accepted_answers":["Versailles-traktatens haarde betingelser skabte okonomisk nod og national ydmygelse i Germany der banede vejen for Hitler"],"review_text":"Anden Verdenskrig voksede direkte ud af Forste. Versailles ydmygede Germany. Den Store Depression forvaerrerede krisen. Hitler lovede at gaengaelde ydmygelsen. Uden Versailles er det svaert at forestille sig Hitlers opkomst."}'::jsonb,
  'mc','short','{"concepts":["Versailles","Hitler","forbindels","WWI-WWII","misconception-uafhaengige"],"misconception_type":"temporal_confusion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"world_war_1"}'::jsonb,
  'mc_single',3,'auto',true,'world_war_1',7,3
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvordan bidrog imperialisme til Forste Verdenskrigs udbrud?","options":["Konkurrence om kolonier i Afrika og Asien skabte spaendinger og fjendskab mellem de europaeiske stormagter","Imperialisme forhindrede krigen fordi kolonier gav lande rigdom nok til at vaere tilfredse","Imperialisme var ikke relateret til krigen som foregik kun i Europa","Kun Frankrig og England rivaliserede om kolonier alle andre lande var tilfredse"],"correct":"Konkurrence om kolonier i Afrika og Asien skabte spaendinger og fjendskab mellem de europaeiske stormagter","accepted_answers":["Konkurrence om kolonier i Afrika og Asien skabte spaendinger og fjendskab mellem de europaeiske stormagter"],"review_text":"I 1914 kontrollerede de europaeiske magter store dele af verden. Konkurrencen om nye kolonier og ressourcer skabte bitter rivalisering. Det styrkede militarismen og skabte en atmosfaere af gensidig mistillid."}'::jsonb,
  'mc','short','{"concepts":["imperialisme","kolonier","rivalisering","spaendinger","MAIN"],"misconception_type":"false_equivalence","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"world_war_1"}'::jsonb,
  'mc_single',3,'auto',true,'world_war_1',7,3
);

-- ─── GRADE 7 · BAND 4 (5 questions) ─────────────────────────────────────────

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad betod skyttegravskrigen for den enkelte soldat i hverdagen?","options":["Konstant frygt, livsvilkaar med rotter og mudder og lange perioder af kedsomhed afbrudt af ekstrem vold","Spaeaendende og heroisk krig med mange muligheder for at vise mod","Komfortabel og rolig tjeneste med god mad","Soldaterne kaeampede kun i korte slag og hvilede resten af tiden"],"correct":"Konstant frygt, livsvilkaar med rotter og mudder og lange perioder af kedsomhed afbrudt af ekstrem vold","accepted_answers":["Konstant frygt, livsvilkaar med rotter og mudder og lange perioder af kedsomhed afbrudt af ekstrem vold"],"review_text":"Skyttegravene var fyldt med mudder, rotter og lig. Soldaterne levede i konstant frygt for artilleri og gasangreb. Perioder af kedsomhed blev brudt af frygtelige angrebsbolger. Mange fik psykologiske skader vi i dag kalder PTSD."}'::jsonb,
  'mc','short','{"concepts":["soldaters hverdagsliv","skyttegraven","PTSD","realitet vs heroisme","misconception-krigen-spaeandende"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"world_war_1"}'::jsonb,
  'mc_single',4,'auto',true,'world_war_1',7,4
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er forkert ved forestillingen om at Germany alene bar ansvaret for Forste Verdenskrig?","options":["Alle de store magter bidrog til optrapningen via militarisme, imperialisme og nationalisme","Forestillingen er korrekt Germany bar fuldt ansvar for krigen","Det er forkert fordi kun Oestrig-Ungarn bar ansvaret","Det er forkert fordi ingen lande bar ansvar krigen startede tilfaeldigt"],"correct":"Alle de store magter bidrog til optrapningen via militarisme, imperialisme og nationalisme","accepted_answers":["Alle de store magter bidrog til optrapningen via militarisme, imperialisme og nationalisme"],"review_text":"Versailles-traktatens krigsscyldsklausul var politisk ikke historisk. England og Frankrig konkurrerede aggressivt om kolonier. Rusland mobiliserede hurtigt. Oestrig-Ungarn udnyttede mordet. Alle store magter bidrog til eskalationen."}'::jsonb,
  'mc','short','{"concepts":["krigsansvar","Germany","delt ansvar","Versailles-klausul","misconception-kun-Germany"],"misconception_type":"overgeneralization","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"world_war_1"}'::jsonb,
  'mc_single',4,'auto',true,'world_war_1',7,4
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Var Versailles-traktaten for haerd mod Germany?","options":["Mange historikere mener den var for haerd fordi den skabte ydmygelse og ekonomisk nod der hjalp Hitler til magten","Traktaten var for mild og det var grunden til at Hitler kom til magten","Traktaten var fuldt retfaerdig og havde ingen negative konsekvenser","Traktaten var irrelevant da Germany ignorerede den fuldstaendigt"],"correct":"Mange historikere mener den var for haerd fordi den skabte ydmygelse og ekonomisk nod der hjalp Hitler til magten","accepted_answers":["Mange historikere mener den var for haerd fordi den skabte ydmygelse og ekonomisk nod der hjalp Hitler til magten"],"review_text":"Fra fransk perspektiv var haardhed forstaaeelig: Frankrig var haerget. Men okenomisten Keynes advarede allerede i 1919 om at betingelserne ville skabe en ny krig. Han fik ret i 1939."}'::jsonb,
  'mc','short','{"concepts":["Versailles","retfaerdig fred","opskrift paa krig","Keynes","Hitler"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"world_war_1"}'::jsonb,
  'mc_single',4,'auto',true,'world_war_1',7,4
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad viser det at England, Frankrig og USA alle brugte propaganda under Forste Verdenskrig?","options":["At demokratier er villige til at manipulere borgerne naar de foeler krigen er eksistentiel og at propaganda ikke er forbeholdt diktaturer","At demokratier var ligesaa slemme som diktaturer","At propaganda altid er etisk i krigstid","At propaganda kun eksisterede i Centraleuropa"],"correct":"At demokratier er villige til at manipulere borgerne naar de foeler krigen er eksistentiel og at propaganda ikke er forbeholdt diktaturer","accepted_answers":["At demokratier er villige til at manipulere borgerne naar de foeler krigen er eksistentiel og at propaganda ikke er forbeholdt diktaturer"],"review_text":"England, Frankrig og USA oprettede dedikerede propagandaministerier. Plakater, film og aviser manipulerede den offentlige mening. Det viser at propaganda er et redskab alle stater griber til i krig uanset styreform."}'::jsonb,
  'mc','short','{"concepts":["propaganda","demokrati","diktatur","misconception-propaganda-kun-diktaturer","manipulation"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"world_war_1"}'::jsonb,
  'mc_single',4,'auto',true,'world_war_1',7,4
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad viser soldaters breve og dagboeger om kloeften mellem officiel propaganda og krigens virkelighed?","options":["At soldaterne oplevede en krig meget forskellig fra den heroiske fremstilling mens censuren forhindrede dem i at fortaelle sandheden hjem","At soldaterne var enige i propagandaens fremstilling","At soldaterne ikke vidste hvad krigen var om","At soldaterne levede komfortabelt og var glade for oplevelsen"],"correct":"At soldaterne oplevede en krig meget forskellig fra den heroiske fremstilling mens censuren forhindrede dem i at fortaelle sandheden hjem","accepted_answers":["At soldaterne oplevede en krig meget forskellig fra den heroiske fremstilling mens censuren forhindrede dem i at fortaelle sandheden hjem"],"review_text":"Soldaternes breve hjem var censurerede. De maatte ikke skrive sandheden. Men dagboeger afslorer den raaende virkelighed: kameraterne der doede, den konstante frygt, meningsloesheden. Der var en enorm kloeft mellem officiel fremstilling og oplevd virkelighed."}'::jsonb,
  'mc','short','{"concepts":["censur","breve","dagboeger","virkelighed vs propaganda","kloeft"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"world_war_1"}'::jsonb,
  'mc_single',4,'auto',true,'world_war_1',7,4
);

-- ─── GRADE 8 · BAND 1 (6 questions) ─────────────────────────────────────────

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad betoekner forkortelsen MAIN som beskriver aarsagerne til Forste Verdenskrig?","options":["Militarisme, Alliancer, Imperialisme og Nationalisme","Moerke, Angreb, Invasion og Neutralitet","Magt, Agression, Interesser og Naboer","Mobilisering, Anneksion, Information og Normer"],"correct":"Militarisme, Alliancer, Imperialisme og Nationalisme","accepted_answers":["Militarisme, Alliancer, Imperialisme og Nationalisme"],"review_text":"Historikere bruger MAIN som huskeregel. Militarisme: rustningskaapplobet. Alliancer: automatiske forpligtelser. Imperialisme: kolonirivalisering. Nationalisme: stolthed og fjendskab. Ingen enkelt aarsag men alle fire samlet."}'::jsonb,
  'mc','short','{"concepts":["MAIN","militarisme","alliancer","imperialisme","nationalisme"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',1,'auto',true,'world_war_1',8,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvilke lande udgoerde Triple Entente og Triple Alliance foer Forste Verdenskrig?","options":["Triple Entente: Frankrig, Rusland og England. Triple Alliance: Germany, Oestrig-Ungarn og Italien","Triple Entente: Germany, Oestrig-Ungarn og Tyrkiet. Triple Alliance: Frankrig, Rusland og England","Begge alliancer bestod af de samme fem lande","Triple Entente: USA, England og Frankrig. Triple Alliance: Germany og Oestrig"],"correct":"Triple Entente: Frankrig, Rusland og England. Triple Alliance: Germany, Oestrig-Ungarn og Italien","accepted_answers":["Triple Entente: Frankrig, Rusland og England. Triple Alliance: Germany, Oestrig-Ungarn og Italien"],"review_text":"Europa var delt i to lejer. Triple Entente vandt. Men ved krigens start skiftede Italien side og England og Frankrig fik USA med i 1917. Alliancerne var ikke faste men de skabte automatiske forpligtelser."}'::jsonb,
  'mc','short','{"concepts":["Triple Entente","Triple Alliance","alliancer","krigsdeltagere"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',1,'auto',true,'world_war_1',8,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvornaar og hvor udkaempedes Forste Verdenskrig?","options":["1914-1918 primaert i Europa men ogsaa i Mellemøesten, Afrika og Asien","1910-1918 kun i Europa","1914-1920 kun paa Vestfronten","1916-1918 primaert i Rusland og Tyrkiet"],"correct":"1914-1918 primaert i Europa men ogsaa i Mellemøesten, Afrika og Asien","accepted_answers":["1914-1918 primaert i Europa men ogsaa i Mellemøesten, Afrika og Asien"],"review_text":"Krigen varede fra august 1914 til november 1918. Vestfronten i Frankrig og Belgien var den mest beromte. Men der var ogsaa Oestfronten mod Rusland, krig i Mellemoeesten, soeslag i Atlanterhavet og kampe om kolonier i Afrika."}'::jsonb,
  'mc','short','{"concepts":["krig 1914-1918","fronter","Vestfronten","global konflikt"],"misconception_type":"scope_confusion","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',1,'auto',true,'world_war_1',8,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad indeholdt Versailles-traktaten fra 1919?","options":["Germany fik skylden for krigen, maatte betale store erstatninger og afgive territorier","Alle lande fik ens betingelser og delte krigsomkostningerne ligeligt","Traktaten garanterede Germany beskyttelse mod fremtidige angreb","Traktaten skabte et forenet Europa med faelles graenser"],"correct":"Germany fik skylden for krigen, maatte betale store erstatninger og afgive territorier","accepted_answers":["Germany fik skylden for krigen, maatte betale store erstatninger og afgive territorier"],"review_text":"Paragraf 231 var krigsscyldsklausulen. Germany fik skylden for hele krigen. Det skulle betale massive erstatninger og afstaa territorier herunder Alsace-Lorraine til Frankrig. Germany mistede ogsaa sine kolonier og store dele af sin haer."}'::jsonb,
  'mc','short','{"concepts":["Versailles","krigsscyldsklausul","erstatninger","territorier","1919"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',1,'auto',true,'world_war_1',8,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvilke nye vaabentyper blev indfoert i Forste Verdenskrig?","options":["Tanks, fly, undervandsbaade og kemiske vaaaben som giftgas","Nukleare bomber og ballistiske missiler","Lasservaaben og droner","Maskingevaeret var den eneste nye teknologi"],"correct":"Tanks, fly, undervandsbaade og kemiske vaaaben som giftgas","accepted_answers":["Tanks, fly, undervandsbaade og kemiske vaaaben som giftgas"],"review_text":"Tanks broede igennem skyttegravslinjer. Fly patruljerede og bombede. Undervandsbaade angreb forsyningsskibe. Giftgas var den mest frygtede nyhed. Alle disse teknologier var nye og aendrede krigsforlobet."}'::jsonb,
  'mc','short','{"concepts":["tanks","fly","undervandsbaade","giftgas","ny teknologi"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',1,'auto',true,'world_war_1',8,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad betod begrebet total krig under Forste Verdenskrig?","options":["At hele samfundet var mobiliseret til krig herunder fabrikker, kvinder, okonomi og propaganda","At krigen foregik 24 timer i dognet uden pauser","At alle militaere ressourcer blev brugt paa een gang","At krigen spredte sig til alle verdensdele"],"correct":"At hele samfundet var mobiliseret til krig herunder fabrikker, kvinder, okonomi og propaganda","accepted_answers":["At hele samfundet var mobiliseret til krig herunder fabrikker, kvinder, okonomi og propaganda"],"review_text":"Total krig betod at skellet mellem civil og militaer sloev. Fabrikker producerede vaaaben. Kvinder arbejdede i industrien. Okonomier blev omstillet til krigsproduktion. Staten kontrollerede madvarer og information. Alle var en del af krigsindsatsen."}'::jsonb,
  'mc','short','{"concepts":["total krig","mobilisering","hjemmefront","stat","civil-militaer"],"misconception_type":"scope_confusion","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',1,'auto',true,'world_war_1',8,1
);

