INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvordan skabte europaeisk imperialisme konkrete spaendinger foer Forste Verdenskrig?","options":["Rivalisering om kolonier i Afrika og Asien skabte gensidig frygt og konkurrence der goerede krig mere sandsynlig","Imperialisme skabte fred fordi lande var for optagede af kolonier til at kaempe mod hinanden","Kun Frankrig og England rivaliserede om kolonier resten var neutrale","Imperialisme var ikke relateret til krigen"],"correct":"Rivalisering om kolonier i Afrika og Asien skabte gensidig frygt og konkurrence der goerede krig mere sandsynlig","accepted_answers":["Rivalisering om kolonier i Afrika og Asien skabte gensidig frygt og konkurrence der goerede krig mere sandsynlig"],"review_text":"Marokko-kriserne i 1905 og 1911 bragte Frankrig og Germany naer ved krig. Konkurrence om Afrika og Asien forstaerkede militarismen. Imperialisme var ikke den eneste aarsag men den bidrog til atmosfaeren af rivalisering."}'::jsonb,
  'mc','short','{"concepts":["imperialisme","kolonier","rivalisering","Marokko-kriserne","spaendinger"],"misconception_type":"causal_inversion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',2,'auto',true,'world_war_1',8,2
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvorfor gik Vestfronten i staa i en blodig doedvande?","options":["Defensiv teknologi som maskingevaerer og artilleri var langt stærkere end angrebsteknologi saa ingen side kunne bryde igennem","Soldaterne paa begge sider naegtede at angribe","Vejrliget umuliggjorde fremrykning","Alliancerne naegtede at sende nok soldater til fronten"],"correct":"Defensiv teknologi som maskingevaerer og artilleri var langt stærkere end angrebsteknologi saa ingen side kunne bryde igennem","accepted_answers":["Defensiv teknologi som maskingevaerer og artilleri var langt stærkere end angrebsteknologi saa ingen side kunne bryde igennem"],"review_text":"Et enkelt maskingevaer kunne holde et helt kompagni tilbage. Artilleri forvandlede slagmarken til mudder. Angreb paa befoestede stillinger kostede enormt mange liv for minimale gevinster. Krigen gik i staa i naesten fire aar."}'::jsonb,
  'mc','short','{"concepts":["Vestfronten","doedvande","defensiv teknologi","angreb","maskingevaer"],"misconception_type":"causal_inversion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',2,'auto',true,'world_war_1',8,2
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvilke konkrete teknikker brugte krigstidens propaganda?","options":["Plakater der fremstillede fjenden som monster, censurerede aviser og film der heroiserede egne soldater","Propaganda var baseret paa faktuelle nyheder","Propaganda brugte kun radio der ikke fandtes foer 1920","Propaganda var frivillig og ingen lande tvang borgere til at se den"],"correct":"Plakater der fremstillede fjenden som monster, censurerede aviser og film der heroiserede egne soldater","accepted_answers":["Plakater der fremstillede fjenden som monster, censurerede aviser og film der heroiserede egne soldater"],"review_text":"Propagandaplakater fremstillede tyske soldater som barbariske mordere. Aviser var censurerede. Film viste heroiske soldater. Maal: faa maeand til at melde sig, faa kvinder til at stoette krigen og fastholde civil moral."}'::jsonb,
  'mc','short','{"concepts":["plakater","censur","film","fjendebillede","propaganda-teknikker"],"misconception_type":"scope_confusion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',2,'auto',true,'world_war_1',8,2
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad betod det at Forste Verdenskrig var en total krig for hjemmefronten?","options":["Staten kontrollerede okonomien, rationerede mad og mobiliserede kvinder til industriarbejde","Civile bag fronten var fuldt beskyttede","Kun civile nær fronten var paavirket","Den civile okonomi voksede og alle levede bedre under krigen"],"correct":"Staten kontrollerede okonomien, rationerede mad og mobiliserede kvinder til industriarbejde","accepted_answers":["Staten kontrollerede okonomien, rationerede mad og mobiliserede kvinder til industriarbejde"],"review_text":"Hjemmefronten var en del af krigen. Mad blev rationeret. Fabrikkerne producerede vaaaben. Kvinder overtog jobs. Staten censurerede pressen. Hjemmefronten var ikke bagland men en aktiv del af krigsindsatsen."}'::jsonb,
  'mc','short','{"concepts":["hjemmefront","total krig","rationering","kvinder","statskontrol"],"misconception_type":"scope_confusion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',2,'auto',true,'world_war_1',8,2
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad fik USA til at gaa ind i Forste Verdenskrig i 1917?","options":["Tysk ubadskrig mod neutrale skibe og Zimmermann-telegrammet der tilbod Mexico amerikansk territorium","USA var allierede med England fra starten","Germany angreb amerikansk territorium direkte","Frankrig var ved at tabe og USA ville redde sine allierede"],"correct":"Tysk ubadskrig mod neutrale skibe og Zimmermann-telegrammet der tilbod Mexico amerikansk territorium","accepted_answers":["Tysk ubadskrig mod neutrale skibe og Zimmermann-telegrammet der tilbod Mexico amerikansk territorium"],"review_text":"USA var neutral fra start. Men Germanys ubadskrig sank civile skibe herunder amerikanske. Zimmermann-telegrammet var et hemmeligt forsoeg paa at overtale Mexico til at angribe USA. Begge dele fik USA med i krigen."}'::jsonb,
  'mc','short','{"concepts":["USA","ubadskrig","Zimmermann-telegram","neutralitet","1917"],"misconception_type":"causal_inversion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',2,'auto',true,'world_war_1',8,2
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad skete der med de store europaeiske imperier som foelge af Forste Verdenskrig?","options":["Det Osmanniske, Oestrig-Ungarnske, Russiske og Tyske kejserrige broede alle samman","Alle imperier overlevede krigen og fortsatte til 1945","Kun Germany mistede sit imperium de andre overlevede","Imperierene forstærkedes fordi de vandt nye kolonier"],"correct":"Det Osmanniske, Oestrig-Ungarnske, Russiske og Tyske kejserrige broede alle samman","accepted_answers":["Det Osmanniske, Oestrig-Ungarnske, Russiske og Tyske kejserrige broede alle samman"],"review_text":"Krigen udraderede fire store imperier. Det Russiske Kejserrige faldt i revolutionen 1917. Oestrig-Ungarn oplostes i mange nye stater. Det Tyske Kejserrige endte. Det Osmanniske Rige oplostes. Europas kort var radikalt forandret."}'::jsonb,
  'mc','short','{"concepts":["imperierenes fald","Rusland","Oestrig-Ungarn","Germany","Osmannerriget","konsekvenser"],"misconception_type":"temporal_confusion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',2,'auto',true,'world_war_1',8,2
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad forklarer at soldaterne fortsatte med at adlyde ordrer selvom de vidste et angreb ville koste mange liv?","options":["Kombination af disciplin, kammeratskab, frygt for doedsstraffen og tro paa at kampen tjente et hoejere formaal","Soldaterne vidste ikke at de ville doe","Soldaterne naegtede faktisk tit og der var konstante mytinier","Soldaterne var paavirket af stoffer og vidste ikke hvad de goerde"],"correct":"Kombination af disciplin, kammeratskab, frygt for doedsstraffen og tro paa at kampen tjente et hoejere formaal","accepted_answers":["Kombination af disciplin, kammeratskab, frygt for doedsstraffen og tro paa at kampen tjente et hoejere formaal"],"review_text":"At naegte en ordre i krig betod doedsstraffen. Kammeratskab betod at man ikke ville svigte dem ved siden af sig. Propaganda overbeviste mange om at de kaeempede for noget vigtigt. Alt dette holdt massedesertioner i skak."}'::jsonb,
  'mc','short','{"concepts":["lydighed","kammeratskab","doedsstraffen","propaganda","disciplin"],"misconception_type":"false_equivalence","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"perspective_shift","challenge_role":"reinforcement","domain":"world_war_1"}'::jsonb,
  'mc_single',2,'auto',true,'world_war_1',8,2
);

