INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er problemet med Versailles-traktatens konklusion om at Germany var eneansvarlig for krigen?","options":["Det var en politisk ydmygelse der ignorerede at alle store magter bidrog til de spaendinger der eksploderede i 1914","Der er intet problem Germany var faktisk eneansvarlig","Problemet er at Rusland og Frankrig burde have delt ansvaret med Germany","Problemet er kun at formuleringen var for mild"],"correct":"Det var en politisk ydmygelse der ignorerede at alle store magter bidrog til de spaendinger der eksploderede i 1914","accepted_answers":["Det var en politisk ydmygelse der ignorerede at alle store magter bidrog til de spaendinger der eksploderede i 1914"],"review_text":"Krigsscyldsklausulen var politisk ikke historisk. Sejrherrerne ville have Germany til at betale. Men England, Frankrig, Rusland og Oestrig-Ungarn bidrog alle til optrapningen. Det er konsensus blandt historikere i dag."}'::jsonb,
  'mc','short','{"concepts":["krigsansvar","Versailles","politisk beslutning","delt ansvar","historisk konsensus"],"misconception_type":"overgeneralization","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"world_war_1"}'::jsonb,
  'mc_single',3,'auto',true,'world_war_1',8,3
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad forklarer at Forste Verdenskrig varede fire aar naer alle forventede den sluttede foer julen 1914?","options":["Defensiv teknologi skaabte en blodig doedvande og ingen side kunne opnaa det afgoorende gennembrud","Lederne paa begge sider onskede bevidst at forlange krigen","Ingen af parterne oenskede fred og forhandling","Vaabenstillstand var ulovlig under international ret"],"correct":"Defensiv teknologi skaabte en blodig doedvande og ingen side kunne opnaa det afgoorende gennembrud","accepted_answers":["Defensiv teknologi skaabte en blodig doedvande og ingen side kunne opnaa det afgoorende gennembrud"],"review_text":"Alle troede krigen ville vaere kort. Schlieffen-planen haabede paa seks uger. Men maskingevaerer og artilleri fastlaaeste fronterne. Ingen teknologi var god nok til at bryde igennem. Fire aars gensidigt blodbad folgede."}'::jsonb,
  'mc','short','{"concepts":["varighed","doedvande","Schlieffen","teknologi","forventninger"],"misconception_type":"causal_inversion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"world_war_1"}'::jsonb,
  'mc_single',3,'auto',true,'world_war_1',8,3
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er den direkte forbindels mellem Versailles-traktaten og Anden Verdenskrigs udbrud?","options":["Traktatens haardhed skabte okonomisk nod og national ydmygelse i Germany der gav Hitler og NSDAP den opbakning de behoevede","Der er ingen forbindels de to traktater var fuldstaendig separate","Traktaten forhindrede faktisk Anden Verdenskrig i 20 aar","Forbindelsen er kun at begge krige begyndte i Europa"],"correct":"Traktatens haardhed skabte okonomisk nod og national ydmygelse i Germany der gav Hitler og NSDAP den opbakning de behoevede","accepted_answers":["Traktatens haardhed skabte okonomisk nod og national ydmygelse i Germany der gav Hitler og NSDAP den opbakning de behoevede"],"review_text":"Den tyske okonomis kollaps under kravet om krigsudgifter og den nationale ydmygelse ved at acceptere eneansvar var giftige betingelser. Da Den Store Depression ramte i 1929 udnyttede Hitler bevidst hadet mod Versailles."}'::jsonb,
  'mc','short','{"concepts":["Versailles","Hitler","NSDAP","Den Store Depression","WWI-WWII forbindels"],"misconception_type":"temporal_confusion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"world_war_1"}'::jsonb,
  'mc_single',3,'auto',true,'world_war_1',8,3
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad betod Forste Verdenskrig for de koloniserede folk i Afrika og Asien?","options":["De blev tvunget til at kaempe og doe i andres krig og fik ikke de friheder de var lovet som beloening bagefter","Koloniserede folk var fuldt frivillige og begejstrede deltagere","Koloniserede folk kaeampede ikke i krigen","Koloniserede folk fik fuld selvstaendighed straks efter krigen"],"correct":"De blev tvunget til at kaempe og doe i andres krig og fik ikke de friheder de var lovet som beloening bagefter","accepted_answers":["De blev tvunget til at kaempe og doe i andres krig og fik ikke de friheder de var lovet som beloening bagefter"],"review_text":"Over en million soldater fra franske og britiske kolonier kaeampede i krigen. Mange var tvangsindrullerede. De fik loefter om politiske reformer. Men efter krigen geninfoerte kolonimagterne det gamle system. Det saaede froe til de nationale befrielsesbevaegelser der folgete."}'::jsonb,
  'mc','short','{"concepts":["kolonier","kolonifolk","tvang","loefter","befrielsesbevaegelser"],"misconception_type":"scope_confusion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"challenge","domain":"world_war_1"}'::jsonb,
  'mc_single',3,'auto',true,'world_war_1',8,3
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad skete der med statens magt over borgerne under Forste Verdenskrig?","options":["Staten fik enorm magt over borgerne via censur, rationering, tvangsindkaldelse og kontrol med okonomien","Statens magt mindsksdes fordi krigen var for kaotisk til at kontrollere","Staten mistede kontrol og borgerne styrede sig selv under krigen","Statens magt aendrede sig ikke under krigen"],"correct":"Staten fik enorm magt over borgerne via censur, rationering, tvangsindkaldelse og kontrol med okonomien","accepted_answers":["Staten fik enorm magt over borgerne via censur, rationering, tvangsindkaldelse og kontrol med okonomien"],"review_text":"Total krig kraevede total kontrol. Staten bestemte hvad aviser maatte skrive. Den rationerede mad. Fabrikker omstillede sig til krigsproduktion. Tvangsindrullering sendte maeand til fronten mod deres vilje. Staten voksede dramatisk under krigen."}'::jsonb,
  'mc','short','{"concepts":["statsmagt","censur","tvangsindkaldelse","rationering","total krig"],"misconception_type":"causal_inversion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"world_war_1"}'::jsonb,
  'mc_single',3,'auto',true,'world_war_1',8,3
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Paa hvilken maade var nationalisme en dobbeltaegget klinge i perioden foer Forste Verdenskrig?","options":["Den styrkede indenrigsk sammenhold men skabte fjendskab og rivalisering mellem nationer der goerede kompromis svaerere","Nationalisme var rent positiv og bidrog ikke til krigen","Nationalisme var rent negativ og ingen saa noget godt i den","Nationalisme opstod som konsekvens af krigen ikke foer den"],"correct":"Den styrkede indenrigsk sammenhold men skabte fjendskab og rivalisering mellem nationer der goerede kompromis svaerere","accepted_answers":["Den styrkede indenrigsk sammenhold men skabte fjendskab og rivalisering mellem nationer der goerede kompromis svaerere"],"review_text":"Nationalisme sammensvejsede franskmæend, tysker og englndsmæend som aldrig foer. Det goerede dem villige til at kaempe. Men det betod ogsaa at man saa fjenden som grundlaeggende anderledes og mindrevaerdig. Det goerede fredelige loesninger svaerere."}'::jsonb,
  'mc','short','{"concepts":["nationalisme","sammenhold","fjendskab","dobbelttydig","kompromis"],"misconception_type":"overgeneralization","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"world_war_1"}'::jsonb,
  'mc_single',3,'auto',true,'world_war_1',8,3
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad betod Forste Verdenskrig for den europaeiske verdensorden der had eksisteret siden 1815?","options":["Den udraderede den gamle orden: fire kejserriger faldt, nye nationer opstod og USA og Sovjet begyndte at erstatte Europa som verdens center","Den bevarede den gamle orden men med Germany som ny dominerende magt","Den styrkede den gamle orden fordi England og Frankrig sejrede","Den europaeiske orden aendrede sig ikke foerend Anden Verdenskrig"],"correct":"Den udraderede den gamle orden: fire kejserriger faldt, nye nationer opstod og USA og Sovjet begyndte at erstatte Europa som verdens center","accepted_answers":["Den udraderede den gamle orden: fire kejserriger faldt, nye nationer opstod og USA og Sovjet begyndte at erstatte Europa som verdens center"],"review_text":"Den europaeiske orden fra 1815 rasede i suel. Kejserriger forsvandt. Graenser blev omtegnet. Wilson introducerede folkenes selvbestemmelsesprincip. Europa var ikke laengere alene om at bestemme verdens skaebne."}'::jsonb,
  'mc','short','{"concepts":["verdensorden","kejserriger","nye nationer","USA","Sovjet","Europa"],"misconception_type":"temporal_confusion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"world_war_1"}'::jsonb,
  'mc_single',3,'auto',true,'world_war_1',8,3
);

